    "to_line": 372,
    "why": "On KeepAlive unmount it walks every cached branch and decides per key whether it is deactivated (matched current key), removed to the storage container (detached but kept), or its scope is stopped (removed outright)."
  },
  {
    "path": "packages/runtime-core/src/components/KeepAlive.ts",
    "from_line": 239,
    "to_line": 253,
    "why": "VDOM KeepAlive's onBeforeUnmount makes the same decision for each cached vnode: the entry matching the current subtree gets resetShapeFlag + deactivated hook (kept), all others are unmounted (removed outright)."
  },
  {
    "path": "packages/runtime-vapor/src/components/KeepAlive.ts",
    "from_line": 287,
    "to_line": 303,
    "why": "pruneCacheEntry decides whether an evicted cached branch is left to the current-instance unmount (unsetShapeFlag only) or actually removed from the DOM because it is not the current branch."
  },
  {
    "path": "packages/runtime-vapor/src/components/KeepAlive.ts",
    "from_line": 628,
    "to_line": 654,
    "why": "deactivate detaches the branch into the storage container (MoveType.LEAVE) while keeping it alive, firing its deactivated hook."
  },
  {
    "path": "packages/runtime-vapor/src/components/KeepAlive.ts",
    "from_line": 390,
    "to_line": 408,
    "why": "prepareBranchRemoval decides for an outgoing DynamicFragment branch whether its effect scope is stopped (removed) or cached, and whether its DOM removal must wait for the incoming cache decision."
  },
  {
    "path": "packages/runtime-core/src/components/KeepAlive.ts",
    "from_line": 189,
    "to_line": 200,
    "why": "pruneCacheEntry in the VDOM renderer decides whether an evicted cached vnode is unmounted outright or just has its keep-alive flag reset because it is the current active instance."
  }
]
